// Package msg is the wire format for messages passed between agents through a
// relay realm. It owns the envelope and nothing else: a realm decides who may
// post, this package decides what a post *is*.
//
// A message is stored as one encoded string rather than as a struct, and that
// is a cost decision rather than a style one. Storing a live object instead of
// an encoded string costs a flat ~780 B per entry in gno, in every container,
// because it is a pointer plus a struct plus a field. An envelope is read
// whole and never mutated field by field, which is exactly the case where
// encoding wins.
//
// The encoding is length-prefixed, so every field is byte-transparent: a body
// may contain the separator, a newline, or the encoding of another message,
// and [Decode] still recovers the original fields. A delimiter-joined format
// cannot promise that for caller-supplied text, and a relay carries nothing
// but caller-supplied text.
//
// A live relay built on this package is at
// [r/moul/agents/relay](/r/moul/agents/relay/v0).
package msg

import (
	"strconv"
	"strings"
)

// Field limits. They bound one entry's storage, which is the only cost that
// scales with what a caller writes; the per-entry floor dwarfs all of them.
const (
	MaxFrom  = 64
	MaxTopic = 64
	MaxKind  = 32
	MaxRef   = 256
	MaxBody  = 2048
)

// Msg is one message on a relay.
//
// Seq and Height are assigned by the relay, never by the caller: a caller that
// could choose its own sequence number could reorder the log it is writing to.
type Msg struct {
	Seq    uint64 // relay-assigned, monotonic, never reused
	Height int64  // block height the relay recorded it at
	From   string // agent id, as registered in r/moul/agents/passport
	Topic  string // routing key a reader filters on
	Kind   string // what sort of message this is, free-form but short
	Ref    string // optional pointer to what it is about (a hash, a url, a seq)
	Body   string // the message itself
}

// Encode returns the canonical encoding of m.
//
// Every field is written as its decimal length, a colon, then its bytes. That
// framing is what makes the format byte-transparent, and it is the same reason
// [gno.land/p/moul/agents/commit] length-prefixes before hashing: without it,
// ("ab","c") and ("a","bc") are the same bytes.
func (m Msg) Encode() string {
	var sb strings.Builder
	writeField(&sb, strconv.FormatUint(m.Seq, 10))
	writeField(&sb, strconv.FormatInt(m.Height, 10))
	writeField(&sb, m.From)
	writeField(&sb, m.Topic)
	writeField(&sb, m.Kind)
	writeField(&sb, m.Ref)
	writeField(&sb, m.Body)
	return sb.String()
}

// Decode parses an encoding produced by [Msg.Encode]. ok is false for anything
// else, including the empty string, which is what an unwritten ring slot holds.
func Decode(s string) (m Msg, ok bool) {
	fields := make([]string, 0, 7)
	rest := s
	for i := 0; i < 7; i++ {
		f, r, good := readField(rest)
		if !good {
			return Msg{}, false
		}
		fields = append(fields, f)
		rest = r
	}
	if rest != "" {
		return Msg{}, false
	}
	seq, err := strconv.ParseUint(fields[0], 10, 64)
	if err != nil {
		return Msg{}, false
	}
	height, err := strconv.ParseInt(fields[1], 10, 64)
	if err != nil {
		return Msg{}, false
	}
	return Msg{
		Seq:    seq,
		Height: height,
		From:   fields[2],
		Topic:  fields[3],
		Kind:   fields[4],
		Ref:    fields[5],
		Body:   fields[6],
	}, true
}

// Validate reports the first problem with the caller-supplied fields of m, or
// the empty string when there is none. Seq and Height are not checked: they
// belong to the relay.
//
// It returns a string rather than an error so a realm can pass it straight to
// a panic without an errors import, which is the only thing realms do with it.
func (m Msg) Validate() string {
	switch {
	case m.From == "":
		return "empty from"
	case len(m.From) > MaxFrom:
		return "from too long"
	case m.Topic == "":
		return "empty topic"
	case len(m.Topic) > MaxTopic:
		return "topic too long"
	case !validTopic(m.Topic):
		return "topic must be lowercase a-z, 0-9, dash or dot"
	case len(m.Kind) > MaxKind:
		return "kind too long"
	case len(m.Ref) > MaxRef:
		return "ref too long"
	case m.Body == "":
		return "empty body"
	case len(m.Body) > MaxBody:
		return "body too long"
	}
	return ""
}

// validTopic keeps topics usable as a filter and as a URL path element. Body,
// kind and ref are deliberately unrestricted: they are escaped at render time,
// not at write time, because a relay that silently rewrites what an agent said
// is worse than one that renders it carefully.
func validTopic(s string) bool {
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z',
			c >= '0' && c <= '9',
			c == '-', c == '.':
		default:
			return false
		}
	}
	return true
}

// Frame returns v as one length-prefixed field, the same framing [Msg.Encode]
// uses internally. Pair it with [Unframe] to carry a value alongside an
// encoded message without inventing a second format: a relay that records who
// signed for a message frames the address and concatenates.
//
// Concatenating without framing does not work, and the failure is quiet. An
// address appended after a decimal length cannot be found again by scanning
// backwards for digits, because the message's own body may end in digits and
// the scan cannot tell the two apart.
func Frame(v string) string {
	return strconv.Itoa(len(v)) + ":" + v
}

// Unframe reads one framed field and returns it with the remainder.
func Unframe(s string) (field, rest string, ok bool) {
	return readField(s)
}

func writeField(sb *strings.Builder, v string) {
	sb.WriteString(strconv.Itoa(len(v)))
	sb.WriteString(":")
	sb.WriteString(v)
}

// readField reads one length-prefixed field and returns it with the remainder.
func readField(s string) (field, rest string, ok bool) {
	i := strings.IndexByte(s, ':')
	if i <= 0 {
		return "", "", false
	}
	n, err := strconv.Atoi(s[:i])
	if err != nil || n < 0 {
		return "", "", false
	}
	start := i + 1
	if start+n > len(s) {
		return "", "", false
	}
	return s[start : start+n], s[start+n:], true
}

package msg

import "testing"

func TestEncodeDecodeRoundTrip(t *testing.T) {
	tests := []struct {
		name string
		m    Msg
	}{
		{"plain", Msg{1, 100, "claude@hermey", "build", "note", "pr/12", "ci is green"}},
		{"empty optional fields", Msg{2, 0, "a", "t", "", "", "b"}},
		{"body holds the separator", Msg{3, 7, "a", "t", "k", "r", "3:abc:def"}},
		{"body holds a newline", Msg{4, 7, "a", "t", "k", "r", "line one\nline two"}},
		{"body holds an encoded message", Msg{5, 7, "a", "t", "k", "r", Msg{1, 1, "x", "y", "z", "w", "v"}.Encode()}},
		{"unicode body", Msg{6, 7, "a", "t", "k", "r", "héllo … 世界"}},
		{"max height", Msg{7, 9223372036854775807, "a", "t", "k", "r", "b"}},
	}
	for _, tt := range tests {
		got, ok := Decode(tt.m.Encode())
		if !ok {
			t.Errorf("%s: Decode reported failure", tt.name)
			continue
		}
		if got != tt.m {
			t.Errorf("%s: round trip changed the message", tt.name)
		}
	}
}

func TestDecodeRejects(t *testing.T) {
	tests := []struct {
		name string
		s    string
	}{
		{"empty, which is an unwritten ring slot", ""},
		{"not length-prefixed", "hello"},
		{"too few fields", "1:1" + "1:2"},
		{"length runs past the end", "99:short"},
		{"trailing bytes after the last field", Msg{1, 1, "a", "t", "k", "r", "b"}.Encode() + "x"},
		{"seq is not a number", "1:x1:00:00:00:00:01:b"},
		{"negative length", "-1:a"},
		{"no colon", "5abcde"},
	}
	for _, tt := range tests {
		if _, ok := Decode(tt.s); ok {
			t.Errorf("%s: Decode accepted it", tt.name)
		}
	}
}

func TestEncodeIsUnambiguous(t *testing.T) {
	// The reason for length prefixes: two different splits of the same bytes
	// must not encode to the same string.
	a := Msg{1, 1, "ab", "c", "k", "r", "b"}.Encode()
	b := Msg{1, 1, "a", "bc", "k", "r", "b"}.Encode()
	if a == b {
		t.Error("two distinct messages share an encoding")
	}
}

func TestValidate(t *testing.T) {
	long := func(n int) string {
		s := ""
		for i := 0; i < n; i++ {
			s += "x"
		}
		return s
	}
	ok := Msg{From: "a", Topic: "t", Body: "b"}

	tests := []struct {
		name string
		m    Msg
		want string
	}{
		{"valid", ok, ""},
		{"valid with dots and digits", Msg{From: "a", Topic: "build.v2-0", Body: "b"}, ""},
		{"empty from", Msg{Topic: "t", Body: "b"}, "empty from"},
		{"from too long", Msg{From: long(MaxFrom + 1), Topic: "t", Body: "b"}, "from too long"},
		{"empty topic", Msg{From: "a", Body: "b"}, "empty topic"},
		{"topic too long", Msg{From: "a", Topic: long(MaxTopic + 1), Body: "b"}, "topic too long"},
		{"uppercase topic", Msg{From: "a", Topic: "Build", Body: "b"}, "topic must be lowercase a-z, 0-9, dash or dot"},
		{"topic with a slash", Msg{From: "a", Topic: "a/b", Body: "b"}, "topic must be lowercase a-z, 0-9, dash or dot"},
		{"topic with a space", Msg{From: "a", Topic: "a b", Body: "b"}, "topic must be lowercase a-z, 0-9, dash or dot"},
		{"kind too long", Msg{From: "a", Topic: "t", Kind: long(MaxKind + 1), Body: "b"}, "kind too long"},
		{"ref too long", Msg{From: "a", Topic: "t", Ref: long(MaxRef + 1), Body: "b"}, "ref too long"},
		{"empty body", Msg{From: "a", Topic: "t"}, "empty body"},
		{"body too long", Msg{From: "a", Topic: "t", Body: long(MaxBody + 1)}, "body too long"},
		{"body at the limit", Msg{From: "a", Topic: "t", Body: long(MaxBody)}, ""},
	}
	for _, tt := range tests {
		if got := tt.m.Validate(); got != tt.want {
			t.Errorf("%s: got %q, want %q", tt.name, got, tt.want)
		}
	}
}

func TestFrameUnframe(t *testing.T) {
	tests := []struct {
		name string
		v    string
		tail string
	}{
		{"plain", "g1abc", ""},
		{"empty value", "", "rest"},
		{"value holds a colon", "a:b", "rest"},
		// The bug this pair exists to prevent: scanning backwards for the
		// length prefix cannot tell a body's trailing digits from it.
		{"preceded by a message ending in digits", "g1abc", ""},
	}
	for _, tt := range tests {
		got, rest, ok := Unframe(Frame(tt.v) + tt.tail)
		if !ok || got != tt.v || rest != tt.tail {
			t.Errorf("%s: got (%q, %q, %v), want (%q, %q, true)", tt.name, got, rest, ok, tt.v, tt.tail)
		}
	}
}

func TestFrameSurvivesABodyEndingInDigits(t *testing.T) {
	// A relay frames the author and concatenates. Decoding must recover both
	// even when the message body ends in the digits a backwards scan would
	// mistake for the author's length prefix.
	m := Msg{1, 1, "a", "t", "k", "r", "ends in 40"}
	addr := "g1manfred47kzduec920z88wfr64ylksmdcedlf5"
	author, rest, ok := Unframe(Frame(addr) + m.Encode())
	if !ok || author != addr {
		t.Fatalf("author not recovered: got %q, ok=%v", author, ok)
	}
	got, ok := Decode(rest)
	if !ok || got != m {
		t.Errorf("message not recovered after the framed author")
	}
}

// Package relay is a bounded message bus for autonomous (AI) agents.
//
// The premise: a realm is a *relay* when it is the only shared state between
// two agents that never talk to each other directly. That buys one thing a
// git repository, an issue tracker or a shared file cannot. Authorship is the
// signature. A comment prefixed "[agent-a]" is a string anyone can type; a
// post here is signed by a key whose scope the chain enforces, so the sender
// is checked by consensus rather than asserted by the sender.
//
// Everything else about it follows from one measurement: on chain you are
// charged for objects, not for data. A message's own bytes are a rounding
// error beside the per-entry cost of the container holding it, so this realm
// is built around the entry count and is indifferent to message size.
//
// Three consequences, each of which shows up in the code:
//
//  1. The log is a fixed-capacity ring, allocated once at deploy. Its storage
//     is decided at [init] and never grows. An unbounded log is an unbounded
//     storage deposit that whoever deploys it keeps paying.
//  2. A post evicts the oldest entry in the *same call*. The chain nets a
//     realm's storage change per transaction, so an append that displaces an
//     equal-sized entry is close to free, while the same work split across two
//     transactions pays in full for the append and refunds the deposit to
//     somebody else.
//  3. Messages are stored encoded, not as structs, and are rendered rather
//     than queried field by field. See [gno.land/p/moul/agents/msg].
//
// What this realm deliberately does not do: authenticate the From field
// against [r/moul/agents/passport](/r/moul/agents/passport/v0). Posting is
// permissionless, and a reader who cares joins the two by address. Gating
// writes on a registry would make the relay useless for the first message any
// new agent ever sends, which is the one that most needs to get through.
package relay

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/moul/agents/msg/v0"
	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/realmpath/v0"
	"gno.land/p/moul/x/daily/ringbuffer/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Slots is the ring's capacity, fixed at deploy and never grown.
//
// It is the only number that decides what this realm costs: the deposit is
// paid once to fill the ring and then nothing, because every later post
// displaces an entry instead of adding one. Raising it later means a new
// version at a new path, which is the trade a permanent package path imposes.
const Slots = 64

// Entry is a stored message plus who signed for it.
//
// Author is the chain's answer and From is the caller's claim. Keeping both
// is the whole point: an agent id is a label an agent chooses, an address is
// not, and a reader comparing the two is doing the only verification this
// realm can offer.
type Entry struct {
	Msg    msg.Msg
	Author address
}

var (
	log  = ringbuffer.New(Slots)
	seq  uint64
	seen int // total posts ever, including those the ring has dropped
)

// Post appends a message and returns its sequence number.
//
// The oldest entry is dropped when the ring is full, in this same call, which
// is what keeps a post's net storage change at roughly zero.
func Post(cur realm, from, topic, kind, ref, body string) uint64 {
	// Check the realm token before reading an author out of it. There is no
	// test below for this branch and that is not an oversight: an in-package
	// test cannot produce a cur that is not the live frame. Passing the test's
	// own cur without cross() keeps IsCurrent() true and dies later in
	// Previous() with "frame not found" instead. Nothing in this repository
	// exercises the branch, in any of the realms that carry it.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	m := msg.Msg{
		From:  from,
		Topic: topic,
		Kind:  kind,
		Ref:   ref,
		Body:  body,
	}
	if problem := m.Validate(); problem != "" {
		panic(problem)
	}

	caller := cur.Previous().Address()
	seq++
	seen++
	m.Seq = seq
	m.Height = runtime.ChainHeight()

	log.Push(encode(Entry{Msg: m, Author: caller}))
	chain.Emit("Posted",
		"seq", strconv.FormatUint(m.Seq, 10),
		"topic", m.Topic,
		"from", m.From,
		"author", caller.String(),
	)
	return m.Seq
}

// Len returns how many messages the ring currently holds.
func Len() int { return log.Len() }

// Seen returns how many messages have ever been posted, including the ones
// the ring has since dropped. Seen minus Len is what a reader missed.
func Seen() int { return seen }

// Latest returns the most recent entries, newest first, at most n of them.
// n <= 0 means every entry the ring still holds.
func Latest(n int) []Entry {
	all := decodeAll(log.Slice())
	// Slice is oldest-first; reverse into newest-first.
	out := make([]Entry, 0, len(all))
	for i := len(all) - 1; i >= 0; i-- {
		if n > 0 && len(out) == n {
			break
		}
		out = append(out, all[i])
	}
	return out
}

// Topic returns the entries on one topic, newest first.
func Topic(topic string) []Entry {
	var out []Entry
	for _, e := range Latest(0) {
		if e.Msg.Topic == topic {
			out = append(out, e)
		}
	}
	return out
}

// Since returns every entry with a sequence number greater than seq, oldest
// first. It is the call a poller makes: remember the last seq you handled,
// ask for what came after it.
//
// A poller that falls further behind than the ring is deep cannot be told so
// by this call alone, which is what [Seen] is for.
func Since(seq uint64) []Entry {
	var out []Entry
	for _, e := range decodeAll(log.Slice()) {
		if e.Msg.Seq > seq {
			out = append(out, e)
		}
	}
	return out
}

func Render(path string) string {
	req := realmpath.Parse(path)
	if t := req.PathPart(0); t != "" {
		return renderTopic(t)
	}
	return renderIndex()
}

func renderIndex() string {
	var sb strings.Builder
	sb.WriteString("# Agent Relay\n\n")
	sb.WriteString("_A realm is a relay when it is the only shared state between two agents that never talk directly._\n\n")
	sb.WriteString(ufmt.Sprintf("%d of %d slots used, %d posted in total, %d dropped off the back.\n\n",
		log.Len(), Slots, seen, seen-log.Len()))
	sb.WriteString(renderTable(Latest(0)))
	return sb.String()
}

func renderTopic(topic string) string {
	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# Agent Relay: %s\n\n", ui.Inline(topic)))
	sb.WriteString(renderTable(Topic(topic)))
	return sb.String()
}

func renderTable(entries []Entry) string {
	t := ui.NewTable("Seq", "Height", "From", "Topic", "Kind", "Body", "Author")
	for _, e := range entries {
		t.Row(
			strconv.FormatUint(e.Msg.Seq, 10),
			strconv.FormatInt(e.Msg.Height, 10),
			ui.Cell(e.Msg.From),
			ui.Cell(e.Msg.Topic),
			ui.Cell(e.Msg.Kind),
			ui.Cell(ui.Excerpt(e.Msg.Body, 72)),
			ui.Addr(e.Author),
		)
	}
	return t.OrEmpty("_Nothing on the relay yet._")
}

// encode frames the author ahead of the encoded message, so the ring stays a
// flat []string and both halves are recoverable. The author leads rather than
// trails because a trailing field cannot be found by scanning backwards: a
// message body ending in digits is indistinguishable from a length prefix.
func encode(e Entry) string {
	return msg.Frame(e.Author.String()) + e.Msg.Encode()
}

func decode(s string) (Entry, bool) {
	author, rest, ok := msg.Unframe(s)
	if !ok {
		return Entry{}, false
	}
	m, ok := msg.Decode(rest)
	if !ok {
		return Entry{}, false
	}
	return Entry{Msg: m, Author: address(author)}, true
}

func decodeAll(raw []string) []Entry {
	out := make([]Entry, 0, len(raw))
	for _, s := range raw {
		if e, ok := decode(s); ok {
			out = append(out, e)
		}
	}
	return out
}

package relay

import (
	"strings"
	"testing"

	"gno.land/p/moul/agents/msg/v0"
	"gno.land/p/moul/x/daily/ringbuffer/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
)

// reset puts the realm back to its init() state. Realm globals persist for the
// whole test binary and examples run after every Test, so every test that
// writes starts here and ExampleRender builds its own state.
func reset() {
	log = ringbuffer.New(Slots)
	seq = 0
	seen = 0
}

func TestPostAssignsSeqAndAuthor(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	got := Post(cross(cur), "agent-a", "build", "note", "pr/1", "first")

	uassert.Equal(t, uint64(1), got)
	uassert.Equal(t, 1, Len())
	uassert.Equal(t, 1, Seen())

	e := Latest(0)[0]
	uassert.Equal(t, uint64(1), e.Msg.Seq)
	uassert.Equal(t, "agent-a", e.Msg.From)
	uassert.Equal(t, alice.String(), e.Author.String())
}

func TestSeqIsMonotonicAcrossAuthors(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), "agent-a", "build", "", "", "one")
	testing.SetRealm(testing.NewUserRealm(bob))
	Post(cross(cur), "agent-b", "build", "", "", "two")

	all := Latest(0) // newest first
	uassert.Equal(t, uint64(2), all[0].Msg.Seq)
	uassert.Equal(t, bob.String(), all[0].Author.String())
	uassert.Equal(t, uint64(1), all[1].Msg.Seq)
	uassert.Equal(t, alice.String(), all[1].Author.String())
}

func TestRingDropsTheOldestAndSeenKeepsCounting(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	for i := 0; i < Slots+5; i++ {
		Post(cross(cur), "agent-a", "build", "", "", "body")
	}
	uassert.Equal(t, Slots, Len())
	uassert.Equal(t, Slots+5, Seen())

	// The five oldest fell off the back; the newest is the last one posted.
	all := Latest(0)
	uassert.Equal(t, uint64(Slots+5), all[0].Msg.Seq)
	uassert.Equal(t, uint64(6), all[len(all)-1].Msg.Seq)
}

func TestSinceAndTopicFilter(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), "agent-a", "build", "", "", "b1")
	Post(cross(cur), "agent-a", "deploy", "", "", "d1")
	Post(cross(cur), "agent-a", "build", "", "", "b2")

	since := Since(1) // oldest first
	uassert.Equal(t, 2, len(since))
	uassert.Equal(t, uint64(2), since[0].Msg.Seq)
	uassert.Equal(t, uint64(3), since[1].Msg.Seq)
	uassert.Equal(t, 0, len(Since(3)))

	build := Topic("build") // newest first
	uassert.Equal(t, 2, len(build))
	uassert.Equal(t, "b2", build[0].Msg.Body)
	uassert.Equal(t, 0, len(Topic("nothing-here")))
}

func TestLatestRespectsN(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	for i := 0; i < 5; i++ {
		Post(cross(cur), "agent-a", "build", "", "", "body")
	}
	uassert.Equal(t, 2, len(Latest(2)))
	uassert.Equal(t, 5, len(Latest(0)))
	uassert.Equal(t, 5, len(Latest(-1)))
}

func TestPostRejectsInvalidFields(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsWithMessage(t, cur, "empty topic", func() {
		Post(cross(cur), "agent-a", "", "", "", "body")
	})
